returns text language sql immutable strict set search_path='' as $$
  select lower(regexp_replace(btrim(translate(p_text,'ёЁ‐‑‒–—−','еЕ------')),'[[:space:]]+',' ','g'))
$$;
revoke all on function finance_private.normalize_business_category(text) from public,anon,authenticated;

create function finance_private.install_business_expenses_20261006(
  p_space_id uuid, p_owner_id uuid, p_expected_old_ids uuid[],
  p_resolutions jsonb default '{}'::jsonb,
  p_expected_reference_ids uuid[] default null
) returns jsonb language plpgsql security invoker set search_path='' as $$
declare
  item record; row record; chosen uuid; parent uuid; candidate text; candidates text[];
  old_ids uuid[]; before_state jsonb; after_state jsonb; backup_data jsonb;
  report jsonb; unresolved jsonb := '[]'::jsonb; moved_expenses integer; moved_transfers integer;
begin
  if current_user <> 'postgres' then raise exception using errcode='42501',message='Run as postgres'; end if;
  -- Serialize reads, reference moves and deletion with all financial writers.
  lock table public.spaces,public.categories,public.expenses,public.incomes,
    public.transfers,public.wallets,public.wallet_opening_balances in access exclusive mode;
  if not exists(select 1 from public.spaces where id=p_space_id and kind='business' and owner_user_id=p_owner_id) then
    raise exception 'Expected owner/business space not found';
  end if;
  select result into report from finance_private.business_expense_installations where space_id=p_space_id;
  if found then return report || jsonb_build_object('already_installed',true); end if;
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into old_ids
    from public.categories where space_id=p_space_id and kind='expense';
  if old_ids is distinct from array(select unnest(p_expected_old_ids) order by 1) then
    raise exception 'Category set changed since local backup; capture a fresh backup';
  end if;
  if p_expected_reference_ids is not null and
    array(select id from (
      select id from public.expenses where category_id=any(old_ids)
      union all select id from public.transfers where fee_category_id=any(old_ids)
    ) refs order by id) is distinct from array(select unnest(p_expected_reference_ids) order by 1) then
    raise exception 'References changed since local backup; capture a fresh backup';
  end if;
  if exists(select 1 from pg_catalog.pg_constraint
    where contype='f' and confrelid='public.categories'::regclass
      and conrelid not in ('public.categories'::regclass,'public.expenses'::regclass,
                         'public.incomes'::regclass,'public.transfers'::regclass)) then
    raise exception 'Unknown category reference table: audit before replacement';
  end if;
  -- All economics and all non-target data must remain byte-for-byte equal.
  select jsonb_build_object(
    'categories', (select coalesce(jsonb_agg(to_jsonb(c) order by id),'[]') from public.categories c where not(space_id=p_space_id and kind='expense')),
    'expenses', (select coalesce(jsonb_agg(to_jsonb(e)-'category_id' order by id),'[]') from public.expenses e),
    'incomes', (select coalesce(jsonb_agg(to_jsonb(i) order by id),'[]') from public.incomes i),
    'transfers', (select coalesce(jsonb_agg(to_jsonb(t)-'fee_category_id' order by id),'[]') from public.transfers t),
    'wallets', (select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') from public.wallets w),
    'opening_balances', (select coalesce(jsonb_agg(to_jsonb(b) order by wallet_id),'[]') from public.wallet_opening_balances b)
  ) into before_state;
  select jsonb_build_object(
    'categories',(select coalesce(jsonb_agg(to_jsonb(c) order by id),'[]') from public.categories c where id=any(old_ids)),
    'expenses',(select coalesce(jsonb_agg(to_jsonb(e) order by id),'[]') from public.expenses e where category_id=any(old_ids)),
    'transfers',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.transfers t where fee_category_id=any(old_ids)),
    'category_imports',(select coalesce(jsonb_agg(to_jsonb(i)),'[]') from finance_private.category_set_imports i where category_id=any(old_ids))
  ) into backup_data;

  -- Compare complete ancestry. Aliases replace only the leaf, never its parent.
  for row in
    with recursive paths as (
      select id,name,parent_id,name::text path from public.categories
        where space_id=p_space_id and kind='expense' and parent_id is null
      union all
      select c.id,c.name,c.parent_id,p.path||' / '||c.name
        from public.categories c join paths p on p.id=c.parent_id
        where c.space_id=p_space_id and c.kind='expense'
    ) select * from paths order by id
  loop
    select array_agg(i.key) into candidates from finance_private.business_expense_items i
      left join finance_private.business_expense_items p on p.key=i.parent_key
      where finance_private.normalize_business_category(row.path)=finance_private.normalize_business_category(i.path)
        or exists(select 1 from jsonb_array_elements_text(i.aliases) alias
          where finance_private.normalize_business_category(row.path)=finance_private.normalize_business_category(
            case when p.key is null then alias else p.path||' / '||alias end));
    candidate := case when cardinality(candidates)=1 then candidates[1] else null end;
    if p_resolutions ? row.id::text then
      candidate := p_resolutions->>row.id::text;
      if not exists(select 1 from finance_private.business_expense_items where key=candidate) then
        raise exception 'Invalid explicit target key for %',row.id;
      end if;
    end if;
    if candidate is null and (
      exists(select 1 from public.expenses where category_id=row.id) or
      exists(select 1 from public.transfers where fee_category_id=row.id)) then
      unresolved := unresolved || jsonb_build_array(jsonb_build_object(
        'old_category_id',row.id,'old_path',row.path,
        'operations',(select count(*) from public.expenses where category_id=row.id),
        'sums',(select coalesce(jsonb_agg(x),'[]') from (
          select currency,count(*) operations,sum(amount_minor)::text amount_minor
          from public.expenses where category_id=row.id group by currency) x),
        'candidate_keys',candidates));
    end if;
    insert into finance_private.business_expense_mapping(space_id,old_category_id,old_path,new_category_key)
      values(p_space_id,row.id,row.path,candidate);
  end loop;
  if jsonb_array_length(unresolved)>0 then
    raise exception using message='Unresolved used business categories',detail=unresolved::text;
  end if;
  if (select count(*) from finance_private.business_expense_mapping where space_id=p_space_id)<>cardinality(old_ids) then
    raise exception 'Invalid old tree: some rows were not reachable';
  end if;

  for item in select * from finance_private.business_expense_items order by (parent_key is not null),sort_order,key loop
    parent := null;
    if item.parent_key is not null then
      select category_id into strict parent from finance_private.business_expense_keys where space_id=p_space_id and key=item.parent_key;
    end if;
    insert into public.categories(space_id,kind,name,parent_id,is_archived,icon_id,sort_order)
      values(p_space_id,'expense',item.name,parent,false,item.icon_id,item.sort_order) returning id into chosen;
    insert into finance_private.business_expense_keys values(p_space_id,item.key,chosen);
  end loop;
  update finance_private.business_expense_mapping m set new_category_id=k.category_id
    from finance_private.business_expense_keys k where m.space_id=p_space_id and k.space_id=m.space_id and k.key=m.new_category_key;
  update public.expenses e set category_id=m.new_category_id
    from finance_private.business_expense_mapping m where m.space_id=p_space_id and e.category_id=m.old_category_id;
  get diagnostics moved_expenses = row_count;
  update public.transfers t set fee_category_id=m.new_category_id
    from finance_private.business_expense_mapping m where m.space_id=p_space_id and t.fee_category_id=m.old_category_id;
  get diagnostics moved_transfers = row_count;
  -- Leaf first: RESTRICT foreign keys protect against any missed reference.
  for row in
    with recursive depth as (
      select id,parent_id,1 n from public.categories where id=any(old_ids) and parent_id is null
      union all select c.id,c.parent_id,d.n+1 from public.categories c join depth d on c.parent_id=d.id where c.id=any(old_ids)
    ) select id from depth order by n desc,id
  loop
    delete from public.categories where id=row.id and space_id=p_space_id and kind='expense';
  end loop;
  if (select count(*) from public.categories where space_id=p_space_id and kind='expense')<>62
    or (select count(*) from public.categories where space_id=p_space_id and kind='expense' and parent_id is null)<>11
    or exists(select 1 from public.categories where id=any(old_ids)) then
    raise exception 'Replacement cardinality failed';
  end if;
  select jsonb_build_object(
    'categories', (select coalesce(jsonb_agg(to_jsonb(c) order by id),'[]') from public.categories c where not(space_id=p_space_id and kind='expense')),
    'expenses', (select coalesce(jsonb_agg(to_jsonb(e)-'category_id' order by id),'[]') from public.expenses e),
    'incomes', (select coalesce(jsonb_agg(to_jsonb(i) order by id),'[]') from public.incomes i),
    'transfers', (select coalesce(jsonb_agg(to_jsonb(t)-'fee_category_id' order by id),'[]') from public.transfers t),
    'wallets', (select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') from public.wallets w),
    'opening_balances', (select coalesce(jsonb_agg(to_jsonb(b) order by wallet_id),'[]') from public.wallet_opening_balances b)
  ) into after_state;
  if before_state is distinct from after_state then raise exception 'Preservation check failed; rolling back'; end if;
  report := jsonb_build_object('space_id',p_space_id,'installed',62,'roots',11,'children',51,
    'deleted',cardinality(old_ids),'remapped_expenses',moved_expenses,'remapped_transfers',moved_transfers,'preserved',true);
  insert into finance_private.business_expense_installations(space_id,package_key,backup,result)
    values(p_space_id,'business_expenses_20261006_v1',backup_data,report);
  return report;
end $$;
revoke all on function finance_private.install_business_expenses_20261006(uuid,uuid,uuid[],jsonb,uuid[]) from public,anon,authenticated;

-- Retire the old business expense seed permanently after successful installation.
-- The existing installer is private and explicitly invoked; nothing runs at login.
alter function finance_private.install_category_set_2026_10_01(uuid)
  rename to install_category_set_2026_10_01_legacy;
create function finance_private.install_category_set_2026_10_01(p_space_id uuid)
returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if current_user<>'postgres' then raise exception 'Run as postgres'; end if;
  if exists(select 1 from finance_private.business_expense_installations where space_id=p_space_id) then
    return jsonb_build_object('space_id',p_space_id,'skipped',true,'reason','Business expense catalog replaced; preserve later edits');
  end if;
  return finance_private.install_category_set_2026_10_01_legacy(p_space_id);
end $$;
revoke all on function finance_private.install_category_set_2026_10_01(uuid) from public,anon,authenticated;
